function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uniq(xs){return [...new Set(xs.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'))}
function statsCardsMarkup(ids=statsPreferences.cards){const values=STATS.summary(games),definitions=new Map(STATS.METRICS.map(metric=>[metric.id,metric]));return ids.map(id=>{const metric=definitions.get(id);return metric?`<div class="stat" data-stat-metric="${id}"><strong>${Number(values[id]||0).toLocaleString('fr-FR')}</strong><span>${esc(metric.label)}</span></div>`:''}).join('')}
function statsColor(index){return `hsl(${Math.round(index*137.508)%360} 72% 58%)`}
function statsLegendMarkup(data,total,hint=''){return `<div class="stats-legend-panel"><ul class="stats-legend" aria-label="Détail complet de la répartition">${data.map((item,index)=>{const percent=total?Math.round(item.value/total*100):0;return `<li><span class="stats-swatch" style="--stats-color:${statsColor(index)}"></span><span>${esc(item.label)}</span><strong>${item.value.toLocaleString('fr-FR')}</strong><small>${percent}%</small></li>`}).join('')}</ul>${hint?`<small class="stats-legend-hint">${esc(hint)}</small>`:''}</div>`}
function statsChartMarkup(view,home=false){const data=STATS.distribution(games,statsPreferences),total=data.reduce((sum,item)=>sum+item.value,0),unit=statsPreferences.measure==='copies'?'exemplaires':'jeux',groupLabels={console:'plateforme',manufacturer:'constructeur',status:'statut',region:'région',format:'format'},groupPlurals={console:'plateformes',manufacturer:'constructeurs',status:'statuts',region:'régions',format:'formats'},scopeLabels={all:'toute la collection',Acquis:'les acquis',Commandé:'les commandés',Recherché:'les recherchés'};if(!data.length)return '<p class="stats-chart-empty">Aucune donnée pour cette sélection.</p>';const description=`${total} ${unit}, ${scopeLabels[statsPreferences.scope]}, répartis par ${groupLabels[statsPreferences.groupBy]}`,heading=`<div class="stats-chart-heading"><p class="eyebrow">${view==='pie'?'RÉPARTITION':'FRISE'} PAR ${groupLabels[statsPreferences.groupBy].toUpperCase()}</p><strong>${esc(description)}</strong></div>`,hint=home&&data.length>5?`${data.length} ${groupPlurals[statsPreferences.groupBy]} affichés · fais défiler la liste`:'';if(view==='pie'){let cursor=0;const slices=data.map((item,index)=>{const start=cursor/total*100;cursor+=item.value;const end=cursor/total*100;return `${statsColor(index)} ${start.toFixed(3)}% ${end.toFixed(3)}%`}).join(',');return `${heading}<div class="stats-pie-layout"><div class="stats-pie" style="--stats-pie:conic-gradient(${slices})" role="img" aria-label="${esc(description)}"><span><strong>${total.toLocaleString('fr-FR')}</strong><small>${unit}</small></span></div>${statsLegendMarkup(data,total,hint)}</div>`}return `${heading}<div class="stats-frieze-strip" role="img" aria-label="${esc(description)}">${data.map((item,index)=>`<span style="--stats-color:${statsColor(index)};--stats-size:${item.value}" title="${esc(`${item.label} : ${item.value}`)}"></span>`).join('')}</div>${statsLegendMarkup(data,total,hint)}`}
function renderStatsDashboard(){const view=statsPreferences.view;statsEls.views.forEach(button=>{const active=button.dataset.statsView===view;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});statsEls.cards.forEach(input=>{input.checked=statsPreferences.cards.includes(input.value)});statsEls.groupBy.value=statsPreferences.groupBy;statsEls.scope.value=statsPreferences.scope;statsEls.measure.value=statsPreferences.measure;statsEls.cardOptions.classList.toggle('hidden',view!=='overview');statsEls.chartControls.classList.toggle('hidden',view==='overview');statsEls.dashboard.innerHTML=view==='overview'?`<p class="stats-dashboard-copy">Cette sélection remplace les statistiques de l’accueil.</p><div class="stats-detail-grid">${statsCardsMarkup()}</div>`:statsChartMarkup(view)}
function renderStatsSummary(){const view=statsPreferences.view,chartView=view!=='overview';els.stats.dataset.statsView=view;els.stats.classList.toggle('stats-home-chart',chartView);if(chartView){els.stats.style.removeProperty('--stats-columns');els.stats.setAttribute('aria-label',view==='pie'?'Statistiques en camembert':'Statistiques en frise');els.stats.innerHTML=`<div class="stats-home-visual">${statsChartMarkup(view,true)}</div>`}else{els.stats.style.setProperty('--stats-columns',String(Math.min(3,Math.max(1,statsPreferences.cards.length))));els.stats.setAttribute('aria-label','Résumé des statistiques');els.stats.innerHTML=statsCardsMarkup()}if(statsEls.dialog.open)renderStatsDashboard()}
function updateStatsPreferences(patch){statsPreferences=STATS.savePreferences({...statsPreferences,...patch});renderStatsSummary()}
function platformTheme(consoleName='',manufacturer=''){const haystack=`${consoleName} ${manufacturer}`.toLowerCase();return PLATFORM_THEMES.find(theme=>theme.match.test(haystack))||{key:'other',color:DEFAULT_ACCENT,mark:'•'}}
function platformStyle(theme){return `--platform-accent:${theme.color};--platform-soft:${theme.color}24${theme.logo?`;--platform-logo:url(assets/platforms/${theme.logo}.svg)`:''}`}
function platformMark(theme,label){const mode=theme.mode||'mask',shape=theme.shape||'emblem',image=theme.logo&&mode==='image'?`<img class="platform-logo-image" src="assets/platforms/${theme.logo}.svg?v=${APP_VERSION}" alt="" loading="lazy">`:'';return `<span class="platform-mark" data-platform-logo="${theme.key}" data-logo-mode="${mode}" data-logo-shape="${shape}" data-has-logo="${theme.logo?'true':'false'}" role="img" aria-label="${esc(label)}">${image}<span class="platform-fallback">${esc(theme.mark)}</span></span>`}
function applyActiveTheme(){const theme=els.cf.value?platformTheme(els.cf.value):els.mf.value?platformTheme('',els.mf.value):null;document.documentElement.style.setProperty('--accent',theme?.color||DEFAULT_ACCENT);document.documentElement.style.setProperty('--accent-soft',theme?`${theme.color}24`:'#f7cf4624');document.body.dataset.activePlatform=theme?.key||'all'}
function populateFilters(manufacturer=els.mf.value,consoleName=els.cf.value){const m=uniq(games.map(g=>g.manufacturer));els.mf.innerHTML='<option value="">Tous les constructeurs</option>'+m.map(x=>`<option>${esc(x)}</option>`).join('');els.mf.value=m.includes(manufacturer)?manufacturer:'';const c=uniq(games.filter(g=>!els.mf.value||g.manufacturer===els.mf.value).map(g=>g.console));els.cf.innerHTML='<option value="">Toutes les consoles</option>'+c.map(x=>`<option>${esc(x)}</option>`).join('');els.cf.value=c.includes(consoleName)?consoleName:'';const fm=$('#manufacturer'),fc=$('#console'),formMakers=uniq([...Object.keys(CONSOLE_CATALOG),...m]),allConsoles=uniq(games.map(g=>g.console));fm.innerHTML=formMakers.map(x=>`<option>${esc(x)}</option>`).join('');fc.innerHTML=allConsoles.length?allConsoles.map(x=>`<option>${esc(x)}</option>`).join(''):'<option>PlayStation 1</option>'}
function visible(){const q=els.search.value.trim().toLowerCase(),mf=els.mf.value,cf=els.cf.value,sf=els.sf.value;return games.filter(g=>(!q||[g.title,g.console,g.manufacturer,g.region,g.format,...(g.tags||[])].join(' ').toLowerCase().includes(q))&&(!mf||g.manufacturer===mf)&&(!cf||g.console===cf)&&(!sf||g.status===sf)).sort((a,b)=>(a.console||'').localeCompare(b.console||'','fr')||(a.title||'').localeCompare(b.title||'','fr'))}
function render(){applyActiveTheme();const has=games.length>0;els.welcome.classList.toggle('hidden',has);els.privacy.classList.toggle('hidden',!has);renderStatsSummary();const makers=uniq(games.map(g=>g.manufacturer));els.cards.innerHTML=makers.map(m=>{const n=games.filter(g=>g.manufacturer===m&&g.status==='Acquis').reduce((s,g)=>s+(g.quantity||1),0),theme=platformTheme('',m);return `<button class="maker-card ${els.mf.value===m?'active':''}" data-maker="${esc(m)}" data-platform="${theme.key}" style="${platformStyle(theme)}">${platformMark(theme,m)}<span class="maker-copy"><strong>${esc(m)}</strong><span>${n} exemplaires · ${uniq(games.filter(g=>g.manufacturer===m).map(g=>g.console)).length} consoles</span></span></button>`}).join('');const v=visible();const label=[els.mf.value,els.cf.value,els.sf.value].filter(Boolean).join(' · ')||'Toute la collection';els.result.textContent=`${label} (${v.length})`;els.list.innerHTML=v.map(g=>{const theme=platformTheme(g.console,g.manufacturer),selected=selectedGameIds.has(g.id),end=selectionMode?`<span class="selection-check" aria-hidden="true">${selected?'✓':''}</span>`:`<div class="qty">${g.quantity>1?`×${g.quantity}`:'›'}</div>`;return `<article class="game-card ${selectionMode?'selectable':''} ${selected?'selected':''}" data-id="${esc(g.id)}" data-platform="${theme.key}" style="${platformStyle(theme)}" ${selectionMode?`role="checkbox" tabindex="0" aria-checked="${selected}"`:''}>${platformMark(theme,g.console)}<div class="game-copy"><h3>${esc(g.title)}</h3><div class="meta"><span class="pill console-pill">${esc(g.console)}</span>${g.region?`<span class="pill">${esc(g.region)}</span>`:''}${g.format?`<span class="pill">${esc(g.format)}</span>`:''}${(g.tags||[]).map(t=>`<span class="pill">${esc(t)}</span>`).join('')}<span class="pill ${STATUS.className(g.status)}">${esc(g.status)}</span></div></div>${end}</article>`}).join('');els.empty.classList.toggle('hidden',v.length>0||!has);const count=selectedGameIds.size,allVisible=v.length>0&&v.every(g=>selectedGameIds.has(g.id));els.selectModeBtn.setAttribute('aria-pressed',String(selectionMode));els.selectModeBtn.setAttribute('aria-label',selectionMode?'Quitter la sélection multiple':'Sélectionner plusieurs jeux');els.selectionBar.classList.toggle('hidden',!selectionMode);els.selectionCount.textContent=`${count} jeu${count>1?'x':''} sélectionné${count>1?'s':''}`;els.selectAllVisible.textContent=allVisible?'Tout désélectionner':`Tout sélectionner${v.length?` (${v.length})`:''}`;els.selectAllVisible.disabled=!v.length;els.bulkEditBtn.disabled=!count}
function setSelectionMode(active){selectionMode=active;if(!active)selectedGameIds.clear();render()}
function toggleVisibleSelection(){const v=visible(),allSelected=v.length&&v.every(g=>selectedGameIds.has(g.id));v.forEach(g=>allSelected?selectedGameIds.delete(g.id):selectedGameIds.add(g.id));render()}
function openBulkForm(){if(!selectedGameIds.size)return;els.bulkForm.reset();['Region','Format','Status','Tags'].forEach(name=>{$(`#bulk${name}`).disabled=true;if(name==='Tags')$('#bulkTagsMode').disabled=true});$('#bulkError').classList.add('hidden');$('#bulkDialogCount').textContent=selectedGameIds.size;els.bulkDialog.showModal()}
function setConsoleOptions(manufacturer,current=''){const existing=games.filter(g=>!manufacturer||g.manufacturer===manufacturer).map(g=>g.console),catalog=CONSOLE_CATALOG[manufacturer]||Object.values(CONSOLE_CATALOG).flat(),consoles=uniq([...existing,...catalog,current]);$('#console').innerHTML=consoles.map(c=>`<option ${c===current?'selected':''}>${esc(c)}</option>`).join('')}
function normalizeTitleLookup(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
function closeTitleSuggestions(message=''){els.titleSuggestions.hidden=true;els.titleSuggestions.replaceChildren();els.title.setAttribute('aria-expanded','false');els.title.removeAttribute('aria-activedescendant');els.titleSuggestionStatus.textContent=message;titleAutocomplete.items=[];titleAutocomplete.activeIndex=-1}
function invalidateTitleSuggestions(message=''){titleAutocomplete.queryRun+=1;clearTimeout(titleAutocomplete.timer);titleAutocomplete.timer=null;closeTitleSuggestions(message)}
function startTitleAutocompleteForm(){titleAutocomplete.formRun+=1;invalidateTitleSuggestions('');els.titleCatalogHelp.textContent=titleCatalogPromise?'Suggestions locales disponibles sur toutes les plateformes. La saisie libre reste possible.':'Tape au moins 2 lettres pour chercher dans la banque locale, toutes plateformes confondues. La saisie libre reste possible.'}
function stopTitleAutocompleteForm(){titleAutocomplete.formRun+=1;invalidateTitleSuggestions('')}
function flattenTitleCatalog(data){if(data?.schema!==1||!Array.isArray(data.platforms))throw new Error('catalog-format');const entries=[];for(const platform of data.platforms){if(!Array.isArray(platform)||platform.length!==4)continue;const[manufacturer,consoleName,qid,titles]=platform;if(!CONSOLE_CATALOG[manufacturer]?.includes(consoleName)||!Array.isArray(titles))continue;titles.forEach((entry,index)=>{const title=Array.isArray(entry)?entry[0]:entry,alias=Array.isArray(entry)?entry[1]:'';if(typeof title!=='string'||!title.trim())return;entries.push({id:`${qid}-${index}`,title,manufacturer,console:consoleName,normalizedTitle:normalizeTitleLookup(title),search:normalizeTitleLookup(`${title} ${alias||''}`)})})}if(!entries.length)throw new Error('catalog-empty');return{count:Number(data.count)||entries.length,entries}}
function loadTitleCatalog(){if(!titleCatalogPromise)titleCatalogPromise=fetch(`assets/data/game-catalog.json?v=${APP_VERSION}`,{headers:{Accept:'application/json'}}).then(response=>{if(!response.ok)throw new Error('catalog-network');return response.json()}).then(flattenTitleCatalog);return titleCatalogPromise}
function titleMatchRank(item,query){if(item.normalizedTitle.startsWith(query))return 0;if(item.search.split(' ').some(word=>word.startsWith(query)))return 1;return item.search.includes(query)?2:-1}
async function searchGameTitles(query){const catalog=await loadTitleCatalog(),currentManufacturer=els.manufacturer.value,currentConsole=els.console.value,ownedKeys=new Set(games.map(game=>`${normalizeTitleLookup(game.title)}|${game.manufacturer}|${game.console}`)),seen=new Set(),matches=[];const consider=(item,owned=false)=>{const key=`${normalizeTitleLookup(item.title)}|${item.manufacturer}|${item.console}`;if(seen.has(key))return;const matchRank=titleMatchRank(item,query);if(matchRank<0)return;seen.add(key);const platformRank=item.console===currentConsole?0:item.manufacturer===currentManufacturer?1:2;matches.push({...item,owned,score:matchRank*100+platformRank*10+(owned?0:1)})};games.forEach((game,index)=>consider({id:`local-${game.id||index}`,title:game.title,manufacturer:game.manufacturer,console:game.console,normalizedTitle:normalizeTitleLookup(game.title),search:normalizeTitleLookup(game.title)},true));catalog.entries.forEach(item=>consider(item,ownedKeys.has(`${item.normalizedTitle}|${item.manufacturer}|${item.console}`)));matches.sort((a,b)=>a.score-b.score||a.title.length-b.title.length||a.title.localeCompare(b.title,'fr')||a.console.localeCompare(b.console,'fr'));return{count:catalog.count,items:matches.slice(0,8)}}
function renderTitleSuggestions(items,run){if(!items.length){closeTitleSuggestions('Aucun titre proposé. Tu peux conserver ta saisie libre.');return}const fragment=document.createDocumentFragment();items.forEach((item,index)=>{const option=document.createElement('li');option.id=`title-suggestion-${run}-${index}`;option.className='title-suggestion';option.role='option';option.dataset.index=String(index);option.setAttribute('aria-selected','false');const copy=document.createElement('span');copy.className='title-suggestion-copy';const title=document.createElement('strong');title.textContent=item.title;const meta=document.createElement('small');meta.textContent=`${item.manufacturer} · ${item.console}`;copy.append(title,meta);option.append(copy);if(item.owned){const owned=document.createElement('span');owned.className='title-suggestion-owned';owned.textContent='Déjà présent';option.append(owned)}fragment.append(option)});els.titleSuggestions.replaceChildren(fragment);els.titleSuggestions.hidden=false;els.title.setAttribute('aria-expanded','true');els.titleSuggestionStatus.textContent=`${items.length} proposition${items.length>1?'s':''}. Utilise les flèches pour parcourir la liste.`;titleAutocomplete.items=items;titleAutocomplete.activeIndex=-1}
function setActiveTitleSuggestion(index){const options=[...els.titleSuggestions.querySelectorAll('[role="option"]')];if(!options.length)return;titleAutocomplete.activeIndex=(index+options.length)%options.length;options.forEach((option,optionIndex)=>option.setAttribute('aria-selected',String(optionIndex===titleAutocomplete.activeIndex)));const active=options[titleAutocomplete.activeIndex];els.title.setAttribute('aria-activedescendant',active.id);active.scrollIntoView({block:'nearest'})}
function chooseTitleSuggestion(index){const item=titleAutocomplete.items[index];if(!item)return;els.title.value=item.title;els.manufacturer.value=item.manufacturer;setConsoleOptions(item.manufacturer,item.console);els.console.value=item.console;invalidateTitleSuggestions(`${item.title}, ${item.console}, sélectionné.`);els.title.focus()}
function requestTitleSuggestions(delay=140){clearTimeout(titleAutocomplete.timer);titleAutocomplete.timer=null;const query=normalizeTitleLookup(els.title.value),formRun=titleAutocomplete.formRun,run=++titleAutocomplete.queryRun;if(query.length<2){closeTitleSuggestions('Tape au moins 2 lettres pour afficher les propositions.');return}els.titleSuggestionStatus.textContent='Recherche dans la banque locale…';titleAutocomplete.timer=setTimeout(async()=>{try{const result=await searchGameTitles(query);if(run!==titleAutocomplete.queryRun||formRun!==titleAutocomplete.formRun||!els.dialog.open)return;els.titleCatalogHelp.textContent=`${result.count.toLocaleString('fr-FR')} références titre/plateforme · ${Object.values(CONSOLE_CATALOG).flat().length} plateformes. La saisie libre reste possible.`;renderTitleSuggestions(result.items,run)}catch{if(run!==titleAutocomplete.queryRun||formRun!==titleAutocomplete.formRun||!els.dialog.open)return;titleCatalogPromise=null;closeTitleSuggestions('La banque de titres est indisponible. La saisie libre reste possible.');els.titleCatalogHelp.textContent='Banque locale indisponible pour le moment. Tu peux saisir le titre librement.'}},delay)}
