$('#tutorialBtn').onclick=event=>openTutorial(event.currentTarget);$('#tutorialCloseBtn').onclick=()=>closeTutorial('close');$('#tutorialSkipBtn').onclick=()=>closeTutorial('skip');tutorialEls.previous.onclick=()=>renderTutorialStep(tutorialStep-1,true);tutorialEls.next.onclick=()=>{if(tutorialStep===tutorialEls.steps.length-1)closeTutorial('complete');else renderTutorialStep(tutorialStep+1,true)};tutorialEls.dialog.addEventListener('cancel',event=>{event.preventDefault();closeTutorial('cancel')});tutorialEls.dialog.addEventListener('close',finishTutorialClose);
['Region','Format','Status','Tags'].forEach(name=>{$(`#applyBulk${name}`).addEventListener('change',e=>{const enabled=e.target.checked;$(`#bulk${name}`).disabled=!enabled;if(name==='Tags')$('#bulkTagsMode').disabled=!enabled;$('#bulkError').classList.add('hidden')})});
els.bulkForm.addEventListener('submit',e=>{e.preventDefault();const applyRegion=$('#applyBulkRegion').checked,applyFormat=$('#applyBulkFormat').checked,applyStatus=$('#applyBulkStatus').checked,applyTags=$('#applyBulkTags').checked;if(![applyRegion,applyFormat,applyStatus,applyTags].some(Boolean)){$('#bulkError').classList.remove('hidden');return}const tags=$('#bulkTags').value.split(',').map(x=>x.trim()).filter(Boolean),tagsMode=$('#bulkTagsMode').value;games=games.map(g=>{if(!selectedGameIds.has(g.id))return g;const updated={...g};if(applyRegion)updated.region=$('#bulkRegion').value;if(applyFormat)updated.format=$('#bulkFormat').value;if(applyStatus)updated.status=$('#bulkStatus').value;if(applyTags)updated.tags=tagsMode==='replace'?tags:uniq([...(g.tags||[]),...tags]);return updated});save();const manufacturer=els.mf.value,consoleName=els.cf.value;populateFilters(manufacturer,consoleName);els.bulkDialog.close();setSelectionMode(false)});
els.form.addEventListener('submit',e=>{e.preventDefault();const id=$('#gameId').value;const obj={id:id||'g'+Date.now(),title:$('#title').value.trim(),manufacturer:$('#manufacturer').value,console:$('#console').value,status:$('#status').value,quantity:Math.max(1,+$('#quantity').value||1),region:$('#region').value,format:$('#format').value,tags:$('#tags').value.split(',').map(x=>x.trim()).filter(Boolean),notes:$('#notes').value.trim(),source:id?(games.find(g=>g.id===id)?.source||'manuel'):($('#entrySource').value||'manuel')};if(id)games=games.map(g=>g.id===id?obj:g);else games.push(obj);save();populateFilters();stopTitleAutocompleteForm();els.dialog.close();render()});
$('#deleteBtn').onclick=()=>{const id=$('#gameId').value;if(id&&confirm('Supprimer ce jeu de RétroMax ?')){games=games.filter(g=>g.id!==id);selectedGameIds.delete(id);save();populateFilters();stopTitleAutocompleteForm();els.dialog.close();render()}};
$('.bottom-nav').addEventListener('click',e=>{const b=e.target.closest('[data-nav]');if(!b)return;document.querySelectorAll('.nav-item[data-nav]').forEach(x=>x.classList.remove('active'));b.classList.add('active');els.sf.value=b.dataset.nav==='wanted'?'Recherché':'';render()});
function chooseImport(){els.file.click()}$('#importBtn').onclick=chooseImport;$('#welcomeImportBtn').onclick=chooseImport;els.file.onchange=e=>{const f=e.target.files?.[0];if(f)importFile(f)};
$('#exportBtn').onclick=()=>{const payload={app:'RétroMax',version:2,exportedAt:new Date().toISOString(),games};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`retromax-sauvegarde-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
populateFilters();render();queueMicrotask(()=>{if(TUTORIAL&&!TUTORIAL.hasSeen())openTutorial(games.length?$('#tutorialBtn'):$('#welcomeImportBtn'))});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
